(function mergeMoreIelts() {
  LEVELS.ielts.forEach(l => {
    const key = 'ielts-' + l.id;
    (MORE_IELTS[key] || []).forEach(w => {
      if (!l.words.some(x => x[0].toLowerCase() === w[0].toLowerCase())) l.words.push(w);
    });
    l.words.forEach(w => { const fix = IELTS_FIXES[key + '|' + w[0]]; if (fix) w[4] = fix; });
  });
})();